// Verification HMAC — signature calculee par le node Crypto 'Compute HMAC'
const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};
const computed = String(input.computed_signature || '').toLowerCase();
const sigHeader = headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '';
const provided = sigHeader.replace('sha256=', '').toLowerCase();

if (!sigHeader) {
  return { hmac_valid: false, error: 'Missing X-Webhook-Signature header', http_code: 401, body, headers };
}
if (!computed) {
  return { hmac_valid: false, error: 'HMAC non calcule (verifier N8N_RAG_WEBHOOK_SECRET / acces $env)', http_code: 500, body, headers };
}
if (provided.length !== computed.length || provided !== computed) {
  return { hmac_valid: false, error: 'Invalid HMAC signature', http_code: 401, body, headers };
}
return { hmac_valid: true, body, headers };

// ============================================
// VALIDATION PAYLOAD - RFC-099 §3.2
// ============================================

const body = $('Verify HMAC').item.json.body;
const errors = [];

// Required fields
const sourceId = body.source_id;
const tenantId = body.tenant_id;
const guildId = body.guild_id;
const botId = body.bot_id;
const scopeId = body.scope_id;
const active = body.active;
const fileType = body.file_type;

// File source (b2_file_key OR url)
const b2FileKey = body.b2_file_key || null;
const url = body.url || null;

// Optional fields
const extractionMethod = body.extraction_method || 'auto';
const title = body.title || null;
const lang = body.lang || null;
const callbackUrls = body.callback_urls || {};
// qdrant_target n'est plus lu : MCP calcule le nom de collection depuis
// l'embedder (azy.daily#223). chat.api peut cesser de l'envoyer quand ça l'arrange.

// Cible et jeton du service qui vectorise. PAS de repli sur $env : il existe
// PLUSIEURS serveurs MCP, et une valeur d'environnement en figerait un seul. Un
// appelant qui omettrait le champ verrait ses documents partir silencieusement
// vers le mauvais MCP — donc dans la mauvaise base vectorielle, sans erreur.
// Même convention que backend_api_url (#386, #413) : l'appelant sait quel service
// il vise, il le dit.
const mcpApiUrl = body.mcp_api_url || null;
const serviceToken = body.service_token || null;

// Embedder du corpus, poussé par chat.api depuis le rag_profile. Sans lui MCP ne
// peut ni choisir l'espace vectoriel ni dériver la collection — et un document
// ingéré avec le mauvais embedder est INVISIBLE au retrieval, sans erreur.
const embedding = {
  provider: body.embedding_provider || null,
  model: body.embedding_model || null,
  dims: body.embedding_dims || null,
  api_key: body.embedding_api_key || null
};

// Volet 2 (tagging) — pass-through depuis le payload (chat.api -> MCP -> n8n)
const controlledVocab = body.controlled_vocab || null;
const authorityRole = body.authority_role || null;
const subjectOverride = body.subject || null;
const docTypeOverride = body.doc_type || null;

// BYOT secrets (payload, plus de process.env dans le sandbox)
const openaiApiKey = body.openai_api_key || null;
const b2BucketUrl = body.b2_bucket_url || null;
const mistralApiKey = body.mistral_api_key || null;
const assemblyaiApiKey = body.assemblyai_api_key || null;

// Validate required
if (!sourceId) errors.push('source_id requis');
if (!tenantId) errors.push('tenant_id requis');
if (!scopeId) errors.push('scope_id requis');
// Exigés explicitement plutôt que repliés sur un défaut : une valeur inventée ici
// écrirait dans le mauvais espace vectoriel, ce qui ne se voit qu'à l'usage — la
// recherche ne rend rien, sans qu'aucune erreur n'ait été levée.
if (!mcpApiUrl) errors.push('mcp_api_url requis dans le payload (plusieurs serveurs MCP : aucun défaut possible)');
if (!serviceToken) errors.push('service_token requis (BYOT, relayé en Authorization: Bearer)');
if (!embedding.provider) errors.push('embedding_provider requis (rag_profile)');
if (!embedding.model) errors.push('embedding_model requis (rag_profile)');
if (!embedding.dims) errors.push('embedding_dims requis (rag_profile)');
if (!embedding.api_key) errors.push('embedding_api_key requis (BYOT)');
// guild_id/bot_id optionnels depuis le decouplage Discord (azy.daily#76)
if (active === undefined || active === null) errors.push('active requis');
if (!fileType) errors.push('file_type requis');
if (!openaiApiKey) errors.push('openai_api_key requis (BYOT embeddings)');
// PDF : mistral_api_key NON requis a priori (Tika gere le natif ; OCR seulement si scanne)
if ((fileType || '').toLowerCase() === 'meeting' && !assemblyaiApiKey) errors.push('assemblyai_api_key requis dans le payload pour la diarisation (file_type meeting)');

// File source validation
if (!b2FileKey && !url) {
  errors.push('b2_file_key ou url requis');
}

// Callback URLs validation
if (!callbackUrls.progress || !callbackUrls.complete || !callbackUrls.error) {
  errors.push('callback_urls.{progress,complete,error} requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    source_id: sourceId
  };
}

return {
  valid: true,
  source_id: sourceId,
  tenant_id: tenantId,
  guild_id: guildId,
  bot_id: botId,
  scope_id: scopeId,
  controlled_vocab: controlledVocab,
  authority_role: authorityRole,
  subject: subjectOverride,
  doc_type: docTypeOverride,
  active: active,
  file_type: fileType,
  b2_file_key: b2FileKey,
  url: url,
  extraction_method: extractionMethod,
  title: title,
  lang: lang,
  callback_urls: callbackUrls,
  mcp_api_url: String(mcpApiUrl).replace(/\/+$/, ''),
  service_token: serviceToken,
  embedding: embedding,
  openai_api_key: openaiApiKey,
  b2_bucket_url: b2BucketUrl,
  mistral_api_key: mistralApiKey,
  assemblyai_api_key: assemblyaiApiKey,
  start_time: Date.now()
};

// ============================================
// CALLBACK PROGRESS - Helper function
// ============================================

const ctx = $('Validate Payload').item.json;

return {
  url: ctx.callback_urls.progress,
  body: {
    status: 'pending',
    progress_percent: 10,
    chunk_count: 0
  },
  context: ctx
};

// ============================================
// EXTRACTION - RFC-099 Phase 2 (transport: this.helpers.httpRequest)
// txt/md=download · pdf=OCR Mistral · audio/video=transcription · meeting=diarisation
// ============================================

const ctx = $('Prepare Callback Start').item.json.context;
const fileType = (ctx.file_type || '').toLowerCase();
const b2FileKey = ctx.b2_file_key;
const url = ctx.url;

if (!b2FileKey && !url) {
  throw new Error('No file source (b2_file_key or url)');
}

let fileUrl;
if (b2FileKey) {
  const B2_BUCKET_URL = ctx.b2_bucket_url || 'https://f005.backblazeb2.com/file/azy-storage';
  fileUrl = `${B2_BUCKET_URL}/${b2FileKey}`;
} else {
  fileUrl = url;
}

// Champs communs exiges par les webhooks MCP (appelant = ingestion RAG)
const mcpCaller = {
  user_id: 'rag-ingest',
  guild_id: ctx.scope_id || ctx.tenant_id || 'rag',
  user_request: 'RAG ingestion extraction'
};
const N8N = 'http://localhost:5678/webhook';
const callWebhook = async (path, body) => {
  const resp = await this.helpers.httpRequest({
    method: 'POST', url: `${N8N}/${path}`, body,
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  });
  return resp.body || resp;
};

const TEXT_TYPES = ['txt', 'md', 'markdown'];
const OCR_TYPES = ['pdf'];
const TRANSCRIBE_TYPES = ['audio', 'mp3', 'mp4', 'wav', 'm4a', 'video', 'mov', 'youtube', 'yt'];
const MEETING_TYPES = ['meeting'];
const OFFICE_TYPES = ['docx', 'xlsx', 'pptx'];

let extractedText = '';
let extractionMethod = '';

if (TEXT_TYPES.includes(fileType)) {
  const raw = await this.helpers.httpRequest({ method: 'GET', url: fileUrl, json: false });
  extractedText = String(raw);
  extractionMethod = 'raw_text';
} else if (OCR_TYPES.includes(fileType)) {
  // PDF HYBRIDE : Tika d'abord (natif, gratuit) ; fallback OCR Mistral si scanne
  const NATIVE_MIN_CHARS = 100;
  let viaTika = '';
  try {
    const off = await callWebhook('office-extractor', { file_url: fileUrl });
    if (off && off.success !== false) viaTika = String(off.text || '').trim();
  } catch (e) { viaTika = ''; }
  if (viaTika.length >= NATIVE_MIN_CHARS) {
    extractedText = viaTika;
    extractionMethod = 'tika_pdf_native';
  } else {
    if (!ctx.mistral_api_key) throw new Error('PDF scanne (texte natif insuffisant): mistral_api_key requis pour OCR');
    const ocr = await callWebhook('pdf-ocr', { provider: 'mistral', file_url: fileUrl, mistral_api_key: ctx.mistral_api_key, ...mcpCaller });
    if (!ocr || ocr.success === false) throw new Error('OCR echec: ' + (ocr && ocr.error && ocr.error.message ? ocr.error.message : 'unknown'));
    extractedText = ocr.text || '';
    extractionMethod = 'mistral_ocr';
  }
} else if (TRANSCRIBE_TYPES.includes(fileType)) {
  // Transcription audio/video (credential Vertex AI cote webhook, pas de cle BYOT)
  const tr = await callWebhook('video-transcription', { video_url: fileUrl, operation: 'transcribe', language: ctx.lang || 'auto', ...mcpCaller });
  if (!tr || tr.success === false) throw new Error('Transcription echec: ' + (tr && tr.error && tr.error.message ? tr.error.message : 'unknown'));
  extractedText = (tr.data && tr.data.transcription) || tr.transcription || '';
  extractionMethod = 'gemini_transcription';
} else if (MEETING_TYPES.includes(fileType)) {
  // Reunion multi-locuteurs -> diarisation (AssemblyAI, BYOT)
  if (!ctx.assemblyai_api_key) throw new Error('assemblyai_api_key requis pour diarisation (file_type=meeting)');
  const sp = await callWebhook('speaker-identifier', { data: fileUrl, source: 'url', assemblyai_api_key: ctx.assemblyai_api_key, ...mcpCaller });
  if (!sp || sp.success === false) throw new Error('Diarisation echec: ' + (sp && sp.error && sp.error.message ? sp.error.message : 'unknown'));
  extractedText = sp.transcript_full || '';
  extractionMethod = 'assemblyai_diarization';
} else if (OFFICE_TYPES.includes(fileType)) {
  const off = await callWebhook('office-extractor', { file_url: fileUrl });
  if (!off || off.success === false) throw new Error('Office extraction echec: ' + (off && off.error && off.error.message ? off.error.message : 'unknown'));
  extractedText = off.text || '';
  extractionMethod = 'tika';
} else {
  throw new Error("Extraction '" + fileType + "' non implementee (txt/md, pdf, audio/video, meeting, youtube). DOCX/XLSX/PPTX via Tika, autres formats: lot suivant (azy.daily#23/#69)");
}

if (!extractedText || extractedText.length === 0) {
  throw new Error('Extraction resulted in empty content');
}

return {
  ...ctx,
  extracted_text: extractedText,
  extraction_success: true,
  extraction_method: extractionMethod,
  char_count: extractedText.length,
  file_size_bytes: extractedText.length
};

// ============================================
// CHUNKING - RFC-099
// ============================================

const ctx = $('Extract Content').item.json;
const text = ctx.extracted_text || '';

// Chunking parameters
const CHUNK_SIZE = 1000; // characters
const CHUNK_OVERLAP = 200; // overlap

const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

// Split by paragraphs
const paragraphs = text.split(/\n\n+/);

for (const para of paragraphs) {
  if (currentChunk.length + para.length > CHUNK_SIZE && currentChunk.length > 0) {
    // Save chunk
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.trim().length
    });
    chunkIndex++;

    // Overlap
    const words = currentChunk.split(' ');
    const overlapWords = words.slice(-Math.ceil(CHUNK_OVERLAP / 5));
    currentChunk = overlapWords.join(' ') + '\n\n' + para;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + para;
  }
}

// Last chunk
if (currentChunk.trim()) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.trim().length
  });
}

return {
  ...ctx,
  chunks: chunks,
  chunk_count: chunks.length
};

// ============================================
// PREPARE CALLBACK COMPLETE
// ============================================

// Le nœud d'écriture Qdrant a disparu : l'indexation est faite par MCP, et
// Vérifier Envoi est ce qui atteste qu'elle a réellement abouti.
const ctx = $('Vérifier Envoi').item.json;

return {
  url: ctx.callback_urls.complete,
  body: {
    success: true,
    chunk_count: ctx.chunk_count,
    chunks_indexed: ctx.chunks_indexed,
    collection: ctx.qdrant_collection || null,
    duration_ms: ctx.duration_ms
  },
  tenant_id: ctx.tenant_id
};

// ============================================
// TAG CONTENT - RFC-106 volet 2 (controlled_vocab + overrides)
// Clés alignées sur la whitelist query: subject, level, notions, doc_type, origin, authority_role, tags
// ============================================

const ctx = $input.first().json;
const cv = ctx.controlled_vocab || {};
const tags = {};

// Dimensions issues du controlled_vocab (pass-through chat.api)
if (cv.subject) tags.subject = cv.subject;
if (cv.level) tags.level = cv.level;
const notions = cv.notions || cv.notion;  // normaliser vers 'notions' (pluriel)
if (notions) tags.notions = notions;
if (cv.doc_type) tags.doc_type = cv.doc_type;
if (cv.origin) tags.origin = cv.origin;
if (cv.tags) tags.tags = cv.tags;

// Overrides declares (precedence — skip inference)
if (ctx.authority_role) tags.authority_role = ctx.authority_role;
if (ctx.subject) tags.subject = ctx.subject;
if (ctx.doc_type) tags.doc_type = ctx.doc_type;

// controlled_vocab absent/null -> aucun tag (inference RFC-099 v1 en lot ulterieur)
return { ...ctx, tags };

// ============================================
// PREPARE CALLBACK ERROR (RFC-093)
// ============================================

const ctx = $('Validate Payload').first().json;
const errItem = $input.first().json || {};
const e = errItem.error || {};
const errMsg = e.message || (typeof e === 'string' ? e : null) || errItem.message || 'processing failed';

return {
  url: ctx.callback_urls.error,
  body: {
    success: false,
    source_id: ctx.source_id,
    error_message: String(errMsg)
  },
  tenant_id: ctx.tenant_id
};

// ============================================
// PRÉPARER TRANCHES — un appel MCP par tranche (azy.daily#223)
// ============================================
//
// n8n ne vectorise plus : il livre des chunks, MCP embarque et écrit. Le nœud
// « Embed + Upsert Qdrant » qui occupait cette place appelait OpenAI en dur,
// créait la collection, et fabriquait des identifiants de point que Qdrant refuse
// (`src_x_chunk_0` → 400, « unsigned integer or UUID »). Aucun point n'a donc
// jamais été écrit.
//
// Pourquoi des tranches
// ---------------------
// Une requête unique portant tous les chunks est fragile : notre découpage fait
// 1 000 caractères, donc un document de 500 000 caractères donne ~625 chunks, soit
// ~700 Ko à embarquer et écrire d'un seul tenant. Des tranches bornées gardent
// chaque requête courte et isolent un échec sur une fraction du travail.
//
// prune_from sur la DERNIÈRE tranche seulement
// --------------------------------------------
// MCP écrit par uuid5(source_id, index) : une ré-ingestion écrase donc en place.
// Les seuls points à supprimer sont les orphelins d'index supérieur, quand la
// nouvelle version compte moins de chunks que l'ancienne.
//
// La purge est en QUEUE, jamais en tête. Purger d'abord aurait ouvert une fenêtre
// où une ingestion interrompue laisse le document amputé — et servi comme complet
// au retrieval. En queue, la source est à tout instant l'ancienne, la nouvelle, ou
// un mélange COMPLET des deux. Une reprise ne peut pas casser un document en base.

const TAILLE_TRANCHE = 200;

const ctx = $('Tag Content').item.json;
const chunks = ctx.chunks || [];
if (chunks.length === 0) {
  throw new Error('Aucun chunk à indexer');
}

const total = chunks.length;
const lots = [];
for (let d = 0; d < total; d += TAILLE_TRANCHE) {
  lots.push(chunks.slice(d, d + TAILLE_TRANCHE));
}

// Le nœud HTTP traite les items séquentiellement et dans l'ordre : la tranche
// portant prune_from part donc bien en dernier, après tous les upserts.
return lots.map((lot, i) => {
  const dernier = i === lots.length - 1;
  const charge = {
    source_id: ctx.source_id,
    scope_id: ctx.scope_id,
    tenant_id: ctx.tenant_id,
    // Tags au niveau document : MCP les réplique sur chaque point. Les envoyer par
    // chunk n'aurait ajouté que du volume sur le fil.
    tags: ctx.tags || {},
    chunks: lot.map(c => ({ index: c.index, text: c.text })),
    embedding_provider: ctx.embedding.provider,
    embedding_model: ctx.embedding.model,
    embedding_dims: ctx.embedding.dims,
    embedding_api_key: ctx.embedding.api_key
  };
  if (dernier) charge.prune_from = total;
  return { json: {
    _tranche: i,
    _nbTranches: lots.length,
    _taille: lot.length,
    url: ctx.mcp_api_url + '/api/rag/chunks',
    service_token: ctx.service_token,
    charge: charge
  }};
});

// ============================================
// VÉRIFIER ENVOI — une tranche perdue vaut échec de l'ingestion
// ============================================
//
// MCP répond {success, indexed, collection}. Avec onError=continueRegularOutput,
// un appel raté n'émet PAS {statusCode, body} mais l'objet d'erreur, sans
// statusCode : le statut réel n'existe que dans le message (« 502 - {…} »).
// Sans cette lecture, une tranche perdue passerait pour indexée et l'ingestion
// se conclurait en succès sur un document incomplet.

const entrees = $input.all();
const lots = $('Préparer Tranches').all();
const ctx = $('Tag Content').item.json;

let indexes = 0;
let collection = null;
const soucis = [];

for (let i = 0; i < entrees.length; i++) {
  const j = entrees[i].json;
  const attendu = ((lots[i] || {}).json || {})._taille || 0;

  let code = j.statusCode;
  if (code === undefined) {
    const brut = String(j?.error?.message || j?.message || '');
    const m = brut.match(/(\d{3})\s*-\s*/);
    code = m ? parseInt(m[1], 10) : ((j?.error || j?.code) ? 502 : 200);
  }
  const corps = j.body || {};

  if (code >= 400 || corps.success === false) {
    soucis.push(`tranche ${i + 1}/${entrees.length} : ${corps?.error?.message || j?.error?.message || ('HTTP ' + code)}`);
    continue;
  }
  const n = typeof corps.indexed === 'number' ? corps.indexed : attendu;
  indexes += n;
  collection = corps.collection || collection;
}

if (soucis.length > 0) {
  throw new Error(
    `Indexation incomplète (${indexes}/${ctx.chunk_count} chunks) — ` + soucis.join(' ; ')
  );
}

return {
  ...ctx,
  mcp_success: true,
  chunks_indexed: indexes,
  qdrant_collection: collection,
  tranches: entrees.length,
  duration_ms: Date.now() - ctx.start_time
};
